.pedagogical-ava-cell{display:grid;justify-items:start;gap:.35rem}.pedagogical-ava-cell small{font-size:.72rem;line-height:1.2}.pedagogical-certificate{display:inline-flex;align-items:center;gap:.28rem;color:var(--inter-accent-dark);font-size:.72rem;font-weight:700;text-decoration:none}.pedagogical-certificate:hover{text-decoration:underline}
